def cycle(hand,queue,card):
    h=list(hand); q=list(queue)
    index=h.index(card)
    h[index]=q.pop(0)
    q.append(card)
    return h,q
def play(state,card):
    s=deepcopy(state)
    if card not in s['hand'] or card not in COSTS or s['elixir']<COSTS[card]:
        return s
    s['elixir']-=COSTS[card]
    s['hand'],s['queue']=cycle(s['hand'],s['queue'],card)
