        s['tower_hp']=max(0,s['tower_hp']-1)
    else:
        building=card in ('X-Bow','Tesla')
        s['units'].append({'card':card,'y':2 if building else 8,'hp':6,'speed':0 if building else 2,'damage':2})
    return s

